<?php
namespace Nakhostin\PerformanceEngine\Admin;
use Nakhostin\PerformanceEngine\Core\Capabilities;
use Nakhostin\PerformanceEngine\Optimization\OptimizationHealthCheck;
final class OptimizationAdminPage { public const SLUG = 'npe-optimization'; private $health; private $capabilities; public function __construct( OptimizationHealthCheck $health, Capabilities $capabilities ) { $this->health = $health; $this->capabilities = $capabilities; } public function register(): void { add_action( 'admin_menu', array( $this, 'menu' ) ); } public function menu(): void { add_submenu_page( AdminPage::SLUG, __( 'Frontend Optimization', 'nakhostin-performance-engine' ), __( 'Optimization', 'nakhostin-performance-engine' ), Capabilities::MANAGE, self::SLUG, array( $this, 'render' ) ); } public function render(): void { if ( ! $this->capabilities->can_manage() ) { wp_die( esc_html__( 'You are not allowed to view optimization diagnostics.', 'nakhostin-performance-engine' ) ); } $url = isset( $_GET['npe_url'] ) ? esc_url_raw( wp_unslash( $_GET['npe_url'] ) ) : home_url( '/' ); $health = $this->health->for_url( $url ); ?><div class="wrap npe-admin" dir="<?php echo esc_attr( is_rtl() ? 'rtl' : 'ltr' ); ?>"><h1><?php echo esc_html__( 'Frontend Optimization Diagnostics', 'nakhostin-performance-engine' ); ?></h1><p><?php echo esc_html__( 'Decisions are read from a precomputed page manifest. Missing or stale manifests leave original assets unchanged.', 'nakhostin-performance-engine' ); ?></p><form method="get"><input type="hidden" name="page" value="<?php echo esc_attr( self::SLUG ); ?>"><label><?php echo esc_html__( 'Page URL', 'nakhostin-performance-engine' ); ?> <input class="regular-text npe-technical" dir="ltr" type="url" name="npe_url" value="<?php echo esc_attr( $url ); ?>"></label> <?php submit_button( __( 'Inspect decisions', 'nakhostin-performance-engine' ), 'secondary', '', false ); ?></form><h2><?php echo esc_html__( 'Manifest health', 'nakhostin-performance-engine' ); ?></h2><p><strong><?php echo esc_html( (string) $health['manifest'] ); ?></strong></p><h2><?php echo esc_html__( 'Feature ownership', 'nakhostin-performance-engine' ); ?></h2><table class="widefat striped"><tbody><?php foreach ( $health['providers'] as $feature => $owner ) : ?><tr><th><?php echo esc_html( $feature ); ?></th><td><?php echo esc_html( $owner ); ?></td></tr><?php endforeach; ?></tbody></table><h2><?php echo esc_html__( 'Decision summary', 'nakhostin-performance-engine' ); ?></h2><table class="widefat striped"><tbody><?php foreach ( $health['decisions'] as $feature => $summary ) : ?><tr><th><?php echo esc_html( $feature ); ?></th><td class="npe-technical" dir="ltr"><?php echo esc_html( wp_json_encode( $summary ) ); ?></td></tr><?php endforeach; ?></tbody></table><h2><?php echo esc_html__( 'Asset decision reasons', 'nakhostin-performance-engine' ); ?></h2><table class="widefat striped"><thead><tr><th><?php echo esc_html__( 'Handle', 'nakhostin-performance-engine' ); ?></th><th><?php echo esc_html__( 'Decision', 'nakhostin-performance-engine' ); ?></th><th><?php echo esc_html__( 'Confidence', 'nakhostin-performance-engine' ); ?></th><th><?php echo esc_html__( 'Reason', 'nakhostin-performance-engine' ); ?></th></tr></thead><tbody><?php foreach ( $health['asset_decisions'] as $decision ) : ?><tr><td class="npe-technical" dir="ltr"><?php echo esc_html( (string) ( $decision['handle'] ?? '' ) ); ?></td><td><?php echo esc_html( (string) ( $decision['decision'] ?? 'keep' ) ); ?></td><td><?php echo esc_html( (string) ( $decision['confidence'] ?? 0 ) . '%' ); ?></td><td><?php echo esc_html( (string) ( $decision['reason'] ?? '' ) ); ?></td></tr><?php endforeach; ?></tbody></table></div><?php } }
